(* [comment removed for export] *)
Ltac hload4 WR A :=
  lazymatch type of WR with wr_at asegs ?mm ?B ?n =>
    let WRC := fresh "WRC" in let junk := fresh "junk" in let CELL := fresh "CELL" in let RD := fresh "RD" in let wv := fresh "wv" in
    assert (WRC : wr_at asegs mm A 4) by (apply (wr_at_sub mm B n); [exact WR| lia| lia| lia]);
    destruct (wr_at_rw_CB mm A 4 WRC ltac:(lia)) as (junk & CELL); change (Z.to_nat 4) with 4%nat in CELL;
    pose proof (rw_cells_read_at asegs mm A [CB 4 junk] 0 (CB 4 junk) 4 (Z_to_bv 64 A) CELL eq_refl eq_refl ltac:(unfold wa; f_equal; lia)) as RD;
    lstep; clear RD;
    lazymatch goal with |- context [sext 64 (bv_extract 0 32 (le_bytes_to_word junk))] =>
      set (wv := sext 64 (bv_extract 0 32 (le_bytes_to_word junk))) in *; clearbody wv end;
    clear CELL WRC junk
  end.
(* [comment removed for export] *)
Ltac hstore4 WR A :=
  lazymatch type of WR with wr_at asegs ?mm ?B ?n =>
    let WRC := fresh "WRC" in let junk := fresh "junk" in let CELL := fresh "CELL" in let SOK := fresh "SOK" in
    assert (WRC : wr_at asegs mm A 4) by (apply (wr_at_sub mm B n); [exact WR| lia| lia| lia]);
    destruct (wr_at_rw_CB mm A 4 WRC ltac:(lia)) as (junk & CELL); change (Z.to_nat 4) with 4%nat in CELL;
    pose proof (rw_cells_store_ok_at asegs mm A [CB 4 junk] 0 (CB 4 junk) 4 (Z_to_bv 64 A) CELL eq_refl eq_refl ltac:(unfold wa; f_equal; lia)) as SOK;
    zstep; clear CELL WRC junk; try store_done
  end.

