Ltac rop_transport m m' MU' WM' OUT :=
  repeat match goal with
  | H : wr_at asegs m ?A ?n |- _ => apply (fun h => wr_at_transport asegs m m' A n h WM') in H
  | H : acc asegs m ?A ?n |- _ => apply (fun h => acc_munch_out m m' _ _ A n MU' OUT ltac:(lia) ltac:(lia) h) in H
  end.

