(* [comment removed for export] *)
Ltac clip_side := first [ flia | lia ].
Ltac clipfix1 :=
  match goal with
  | |- context [bv_swrap 32 (?x mod 18446744073709551616 + ?y mod 18446744073709551616)] => rewrite (swrap32_mm x y) by clip_side
  | |- context [?x mod 18446744073709551616] => rewrite (Z.mod_small x 18446744073709551616) by clip_side
  | |- context [Z.land ((bv_signed (Z_to_bv 64 ?x) / 9223372036854775808) mod 18446744073709551616) ?x] => rewrite (clip_min0 x) by clip_side
  | |- context [Z.land (bv_swrap 32 (0 - Z.b2z (9223372036854775808 <? Z.lxor (?h mod 18446744073709551616) 9223372036854775808)) mod 18446744073709551616) (?h mod 18446744073709551616)] =>
      rewrite (clip_hang h) by clip_side
  | |- context [Z.land ((0 - Z.b2z (9223372036854775808 <? Z.lxor (?h mod 18446744073709551616) 9223372036854775808)) mod 18446744073709551616) (?h mod 18446744073709551616)] =>
      rewrite (clip_hang64 h) by clip_side
  | |- context [Z.land (bv_swrap 32 (0 - Z.b2z (9223372036854775808 <? Z.lxor ?x 9223372036854775808)) mod 18446744073709551616) ?x] => rewrite (clip_max0 x) by clip_side
  | |- context [Z.land ((0 - Z.b2z (9223372036854775808 <? Z.lxor ?x 9223372036854775808)) mod 18446744073709551616) ?x] => rewrite (clip_max0n x) by clip_side
  end.
Ltac clipfix := repeat clipfix1; swrap32_fix; rewrite ?Z.add_0_l, ?Z.sub_0_r, ?Z.add_0_r.

